+      color: var(--accent);
+      font-size: 0.9rem;
+      font-weight: 700;
+      letter-spacing: 0.02em;
+      text-transform: uppercase;
+    }
+
+    h1 {
+      margin: 20px 0 12px;
+      font-size: clamp(2.2rem, 5vw, 4rem);
+      line-height: 1.05;
+    }
+
+    .hero p {
+      margin: 0;
+      max-width: 640px;
+      color: var(--muted);
+      font-size: 1.05rem;
+      line-height: 1.7;
+    }
+
+    .faq {
+      margin-top: 28px;
+      display: grid;
+      gap: 16px;
+    }
+
+    .example {
+      border: 1px solid var(--line);
+      border-radius: var(--radius);
+      background: var(--surface);
+      box-shadow: 0 12px 32px rgba(24, 36, 57, 0.08);
+      overflow: hidden;
+      backdrop-filter: blur(14px);
+      transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
+    }
+
+    .example:hover {
+      transform: translateY(-2px);
+      box-shadow: 0 18px 34px rgba(24, 36, 57, 0.12);
+      border-color: rgba(91, 124, 255, 0.2);
+    }
+
+    .question {
+      width: 100%;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 20px;
+      padding: 22px 24px;
+      border: 0;
+      background: transparent;
+      color: inherit;
+      font: inherit;
+      font-size: 1.05rem;
+      font-weight: 700;
+      text-align: left;
+      cursor: pointer;
+    }
+
+    .question:focus-visible {
+      outline: 3px solid rgba(91, 124, 255, 0.28);
+      outline-offset: -3px;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 36px;
+      height: 36px;
+      display: grid;
+      place-items: center;
+      border-radius: 50%;
+      background: var(--accent-soft);
+      color: var(--accent);
+      font-size: 1.3rem;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .example.open .icon {
+      transform: rotate(45deg);
+      background: rgba(91, 124, 255, 0.18);
+    }
+
+    .details {
+      display: grid;
+      grid-template-rows: 0fr;
+      transition: grid-template-rows 220ms ease;
+      border-top: 1px solid transparent;
+    }
+
+    .example.open .details {
+      grid-template-rows: 1fr;
+      border-top-color: var(--line);
+    }
+
+    .details-inner {
+      min-height: 0;
+      overflow: hidden;
+    }
+
+    .details p {
+      margin: 0;
+      padding: 0 24px 22px;
+      color: var(--muted);
+      line-height: 1.7;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        width: min(100% - 20px, 960px);
+        padding: 32px 0 48px;
+      }
+
+      .hero {
+        padding: 24px;
+      }
+
+      .question {
+        padding: 18px 18px;
+      }
+
+      .details p {
+        padding: 0 18px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main class="page">
+    <section class="hero">
+      <span class="eyebrow">Cat care FAQ</span>
+      <h1>Everything curious humans ask about cats.</h1>
+      <p>
+        Explore quick answers about behavior, routines, and wellbeing. Each question starts collapsed,
+        so the page stays clean until you open what you want to read.
+      </p>
+    </section>
+
+    <section class="faq" aria-label="Frequently asked questions about cats">
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span>Why do cats purr?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <div class="details-inner">
+            <p>
+              Cats often purr when they feel safe and content, but they can also purr when they want comfort.
+              It is a flexible behavior used during relaxation, bonding, and even stressful moments.
+            </p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span>How much do indoor cats sleep?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <div class="details-inner">
+            <p>
+              Many indoor cats sleep between 12 and 16 hours a day. Their bursts of energy are usually short,
+              which makes long naps a normal part of a healthy routine.
+            </p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span>Why do cats knead soft blankets?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <div class="details-inner">
+            <p>
+              Kneading is a comforting instinct that starts in kittenhood. Adult cats may do it when they feel
+              relaxed, are preparing a cozy resting spot, or are showing affection.
+            </p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span>Do cats need daily playtime?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <div class="details-inner">
+            <p>
+              Yes. Short, engaging play sessions help cats stay active, reduce boredom, and satisfy their hunting
+              instincts. Wand toys, chasing games, and puzzle feeders are great options.
+            </p>
+          </div>
+        </div>
+      </div>
+
+      <div class="example">
+        <button class="question" type="button" aria-expanded="false">
+          <span>What is the best way to help a cat feel at home?</span>
+          <span class="icon" aria-hidden="true">+</span>
+        </button>
+        <div class="details">
+          <div class="details-inner">
+            <p>
+              Give them a quiet place to hide, easy access to food and water, a clean litter box, and time to adjust.
+              Most cats settle in faster when they can explore new spaces gradually and on their own terms.
+            </p>
+          </div>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <script>
+    document.querySelectorAll(".example").forEach(function (item) {
+      var button = item.querySelector(".question");
+
+      button.addEventListener("click", function () {
+        var isOpen = item.classList.toggle("open");
+        button.setAttribute("aria-expanded", String(isOpen));
+      });
+    });
+  </script>
+</body>
+</html>
*** End Patch
